tolerances=[{'quantity':'ground roots, relative assembly roots, semantic sockets, facing rotations','law':'Exact authored values within1e-5 world units/radians; unit scale within1e-6. No sprite shift, subject fitting or per-view transform.','reason':'A1e-5-world discrepancy projects .00128 logical ground pixels.'},{'quantity':'asset frame/atlas/order/timing/footprint','law':'Exact logical192x352, native384x704, root96,248, sourceScale2, cell128; N/E/S/W; one static frame at12fps, loopfalse; occupied/support onecell unchanged.','reason':'Consumer registration/packing is integer contract.'},{'quantity':'registered camera/calibration','law':'Asset-specific55.0079798-degree orthographic square top/front, aspect1.2206555605:1; one shared rig, logical basis X(128,0), depth(0,128), height(0,-89.6), root(96,248), each within .02logicalpx. Record matrices/ortho/shift per canvas.','reason':'Saved character camera is unrelated; subpixel meaningful check rather than binary float equality.'},{'quantity':'entry solid envelope after structural rebuild','law':'Native solid geometry entry-local Y[-.5,0] within1e-5 numerical noise, X[-.51,.51] at most baseline cap envelope, Z[0,.49]. No hidden or isolated inboard helper solids/card, negative ground penetration, ground shadow or post/cap intrusion past planeY0. Nominal onecell footprint/root remain unchanged.','reason':'Actual source caps exceed halfwidth by .01; this is a maximum visual envelope, not an instruction to expand. Exterior-only geometry eliminates overlap instead of preserving buried arrangement.'},{'quantity':'terminal support/contact profile','law':'Usable stair flight rises monotonically from ground approach to horizontal terminal contact topZ.22 at localY0. Contact must cover the editor-declared centered terminal width W, .76<=W<=.96. At the shared boundary, entry/deck topsZ.22 and paired profile mismatch must match within1e-5 world; broad decorative walking top away from the boundary may vary±.002. No uncovered run gap or projecting obstacle. Boundary planeY0 matched within1e-5 world.','reason':'Exact shared contact is natively attainable and projects .000896logical vertical px at1e-5world. Broad .002 decorative relief is .1792logicalpx; no finite run-gap allowance. Sound construction/step count is editor-owned.'},{'quantity':'central clearance','law':'Continuous centered unobstructed clear walking width>=.76 world (innerpostX±.38), within1e-5. No raised trim, grain/fasteners or rail crossing that corridor; walking relief≤.002 and no hole/separate unsupported sliver.','reason':'Measured source post inneredges establish actual minimum passage.'},{'quantity':'floor transfer correction bounds','law':'Only functional edge-profile correction is in floor-local X[-.50,.50],Y[-1.50,-1.48]; never beyond3x3footprint. Within that strip provide continuous Z.22 support across X[-.48,.48], closing throughgaps and the endbevel only as necessary; join boundary top .22 within1e-5 world. Preserve global broad .22 walkingheight and max .25 envelope. No notch, recess/channel, global height/root change or lip.','reason':'Source endbevel is .008world; .02-deep inward strip comfortably contains repair while staying0.02/3 of deck run. .02 lateral buffer on .96-width source treads avoids forcing contact onto a plank throughgap.'},{'quantity':'native and consumer connected visibility/coverage','law':'At original roots current consumer order must reproduce native visibility for all4facings, including posts/undersides. Inspect premultipliedRGB+alpha, ordinary viewer filtering and quarter-logical-pixel phases. No accidental sustained visible seam>=.5logicalpx, black crack, alpha hole, ghost tread, occluded cap or detached detail. Registered projected boundaries should agree within .25logicalpx; larger localized differences require explanation/repair, not global numeric color matching.','reason':'Quarterlogicalpx is halfnativepixel at2x. Native raw depth/contact and filtering each need their own evidence; opacity alone does not prove physical support.'},{'quantity':'light symmetry and clean alpha','law':'One horizontally symmetric lighting/material recipe for allfacings; symmetric native cardinal light energy/colors within .5% if used. No preferred horizontal key, directional groundshadow, target halo or partial-alpha bright/red fringe visible at logical/phone size on light/gray/dark.','reason':'Outcome-based softness; source wattages, roughness and contrast are not aesthetic locks.'}]
contract={'asset':'dock-entry','status':'proposed; coordinator accepted preferred structural direction, shared floor reconciliation/brief freeze still required','approvalAtThisStage':False,'initialIndependentObservation':{'path':'initial.json','sha256':H(OUT/'initial.json'),'independence':'Written before floor technical proposals; no other-object aesthetic criteria or editor proposals read.'},'sourceIdentity':{'project':str((AS/'production/source/blender/revisions/b1765262bfa897ad/sushi-loop-world-library.blend').relative_to(ROOT)),'sha256':'b1765262bfa897adf7e5de4f2b866cfc939430cf18539f3f7063859b9cff31c6','scene':'S33 Native Asset Library Export','collection':'S33_PROP_dock-entry.001','root':'dock-entry__root.001','savedActiveCamera':'S33 Capture Camera.240 is unrelated35degree character capture; do not reuse its settings','ownResourceSemantics':'Three native wood materials; no entry image nodes, armatures, actions/drivers/NLA. Native beveled editable geometry, no target card.'},'capture':{'nativeFrame':[384,704],'logicalFrame':[192,352],'logicalRoot':[96,248],'sourceScale':2,'logicalCellSize':128,'worldUnitsPerCell':1,'facings':{'N':'rootZrotation pi','E':'rootZrotation +pi/2','S':'rootZrotation0','W':'rootZrotation -pi/2'},'static':{'frames':1,'fps':12,'loop':False},'projection':'oblique square top/front; asset guide/source-camera/calibration, not active scene','historicalSourceScale4':'Historical4x source captures are not the published2x atlas. Later packet must bind actual raw captures and exact downsample recipe; no claim that2x independent reproduction is byte-identical to old4x.'},'placementAndContacts':{'footprint':[1,1],'rootCell':[.5,.5],'occupiedCells':[[0,0]],'supportCells':[[0,0]],'sourceHeightNominalEnvelope':.49,'sourceMeasuredEnvelope':[[-.51,-.495,-.01],[.51,.495,.4825]],'sourceTreadProfileLaw':'Centers(0,-.375+.25*i,.04+.045*i); dimensions(.96,.24,.10); bevel .012; flat tops .09+.045*i; localY interboard gaps .01. Full evaluated vertices/faces and BVH profiles saved.','sourceDeclaredSockets':{'entry':[0,-.5,0],'dock':[0,.5,.23]},'interpretation':'Entry marker is ground approach. Dock marker lies halfcell inside the floor at world(0,-1,.23), not the transfer boundary or measured mesh top. Markers remain exact; do not falsely make nominal .49 a tread height or .23 a broad walking surface.','relativeRootToFloor':[0,-1.5,0],'actualTransferPlane':{'entryLocalY':0,'floorLocalY':-1.5,'commonTangent':'X','travelTowardDeck':'+entryY','commonHeight':.22},'sharedNeighborPolicy':'Preserve workshop(.78,.35,.23), submarine(-.70,-.42,.23), cover(0,0,.23) placement/clearance. Existing .035/.055 hut/sub support gaps are scoped to later native family support repair; no false zero-gap claim or neighbor edit here.'},'preferredCoordinatedCorrection':{'id':'exterior-half-native-flight','acceptedByCoordinator':True,'problemFixed':['Submerged inboard entry geometry and whole-sprite/native visibility disagreement','Genuine .005world exterior run gap and ambiguous nominal-vs-actual contact law'],'entryConstructionOutcome':'Rebuild a coherent native stair unit entirely in entry-local y[-.5,0], including capped posts/side structure. Usable centered flight rises monotonically to .22 at y0. The dock supplies walking surface for entry-local y[0,.5]. Keep original onecell occupancy, root/camera/frame, marker coordinates, recognizable warm timber entry role, support and clearance. Step count, construction and purposeful details remain editor-owned.','floorConstructionOutcome':'Fill/flatten only bounded central edge transfer strip X[-.50,.50],Y[-1.50,-1.48] to common .22 surface overX[-.48,.48]. This may close native plank gaps at the contact and remove old endbevel dip; no notch, altered broad walkingheight, footprint expansion or root shift.','minimumDependencies':['Root reconciles/freezes identical plane,height,width,repairstrip and envelope terms in both briefs before either editor construction.','Both editors receive each other\u2019s immutable candidate geometry or agreed evaluated boundary profile to demonstrate a matching contact; final coupled hashes bound in evidence.','Exact four native standalone entry atlases remain ordinary registered384x704 assets. No new clip or gameplay behavior required by this proposal.','All4 native connected joins plus independently assembled actual candidate sprites at unchanged roots must validate current orderPlacements. Source physical rotation yields N floor-last, S/E/W entry-last; no adapter presumed passing before proof.','If native geometry still cannot pass current consumer ordering/filtering, stop for shared reconciliation rather than quietly adding masks/painted patches or changing the frozen structure.'],'whySufficientInPrinciple':'All native entry solids are exterior to deck interior, removing the source overlap rather than trimming a guessed buried tread. In S entry is foreground; N deck is foreground; E/W exterior entry and deck occupy disjoint projected X halfplanes at the contact. Current consumer sorting is therefore consistent in principle, while actual proof remains mandatory.','prohibitedWorkarounds':['Preserving/painting over source submerged tread','Blanket deletion justified only by AABB (source grooves expose slivers)','Floor-only notch/recess that invents a stair channel','Per-facing roots/camera fit, colored alpha patch, target image card','Unrequested Godot or gameplay rollout; dock/entry are outside existing Godot34selection']},'fallbackNotCurrentContract':{'description':'If the exterior-half structural plan fails an actual role/visibility constraint, a native connected-entry contribution variant against exact candidate deck depth plus explicit connected-group floor-first selection is a possible later reconciled alternative.','requiresNewSharedReconciliation':True,'mustNotBeAddedSilently':True,'note':'No adapter implemented or required under current preferred plan.'},'tolerances':tolerances,'verifiedBaselineDefects':'own-interface-measurements.json::verifiedFindings','technicalEvidence':[{'path':p,'sha256':H(OUT/p)} for p in ['own-native-inspection.json','own-saved-source-semantics.json','own-native-geometry-and-captures.json','own-interface-measurements.json','own-consumer-order.json','own-published-assembly-evidence.json','own-joins-comparison.png']],'floorTechnicalProposalsReadAfterInitial':[{'path':str((AS/f'refinement/objects/dock-floor/reviews/{p}').relative_to(ROOT)),'sha256':H(AS/f'refinement/objects/dock-floor/reviews/{p}')} for p in ['source-contract-proposal.json','interface-correction-options.json']],'remainingActions':'Root/floor judge reconcile exact strip/profile before freezing brief; editors pending; later all-facing capture/consumer/context proof; no candidate approval.'}
write('source-contract-proposal.json',contract)
criteria={'asset':'dock-entry','status':'independent proposed visible criteria; shared technical freeze pending','basis':{'initial':'initial.json','initialSHA256':H(OUT/'initial.json'),'fixedTarget':'../inputs/target.png','targetSHA256':'a5b7676ecd8d72f005dec527e2cb0adf8b9e28e4cc6416fb8c18ca7cd9676b7f','styleReference':'../../../style/warm-soft-reference.png','nativeReconstruction':'Useful structural/forms/detail improvements encouraged; no lock on source part count or awkward inboard tread arrangement. No other-object aesthetic criteria read.'},'visibleSuccessCriteria':[{'dimension':'shapeVolume','outcome':'At logical size the unit reads as a stout, usable crafted timber stair entry. Treads/rises/side construction and capped posts have clean purposeful proportions and believable connection/support. Softer bevel transitions give weight and roundness without blobby edges. Rebuilt exterior-half stairs may differ from target/source count, but need a coherent rising path meeting the deck and a clear centered passage.','reject':'Flat alternating color rectangles as the only depth cue, floating posts/fasteners, paper-thin disconnected boards, hidden stair continuation painted above deck, collisions, unsupported gaps, accidental silhouette clipping.'},{'dimension':'color','outcome':'Warm honey/gold walking surfaces, richer reddish/orange brown supporting wood, darker controlled creases; restrained compatible warm metal or dark fixing color where useful. Large planes retain hue/value information, with enough separation to read each step at192x352/128pxcell.','reject':'Blown yellow/white cap panels, black dead risers/undersides, muddy orange wash merging all forms, unrelated palette/metal dominance.'},{'dimension':'lightingHighlights','outcome':'Broad soft highlights on top edges and caps describe the native curvature. Local contact shading can add depth while inner tread corners and undersides remain readable. All4facings share one horizontally symmetric warm-light treatment, with no directional groundshadow.','reject':'One-sided global brightening, hard directional key/cast-ground shadow, bright pixel fringe copied from target, clipped hot strips, abrupt normals/faceted seams that look broken rather than stylized.'},{'dimension':'materialDetail','outcome':'Wood has controlled broad native/procedural/packed grain or endgrain where it survives intended size. Purposeful fasteners/joinery/side construction add useful hierarchy and physical clarity, inspired by target round fixings and timber edge treatment. Small details are firmly attached, spaced deliberately and clear of walking path.','reject':'Dense hairline noise, decal-like illegible black scribbles, identical obvious texture stamps, tiny random bolt clutter, detached/highlight-only metal dots, grain that changes scale/swims across facings. No mandatory decoration count or shader recipe.'},{'dimension':'artifactFreeReadability','outcome':'Inspect enlarged, logical and actual phone/landscape consumer evidence. Silhouette/step edge rhythm reads immediately on light/gray/dark. Contact joins have clean RGB and alpha, without ghost stairs, floor holes, black cracks, red/yellow ringing, clipped geometry or detached detail. Allfacings remain coherent beyond single-view target.','reject':'Successful single S render while N/E/W fail, gaps hidden only by dark background, filtering seams, unreported consumer draw-order override, native-render/composite mismatch.'}], 'technicalAcceptance':'source-contract-proposal.json::tolerances','laterRequiredCoverage':[{'group':'immutableNativePacket','required':['Editable candidate blend plus dependency closure, exact source hash, target/style/input hashes, recipe/scripts, scene/camera/root/matrix/render/lighting/material/resource evidence. No image card or paintover.','All evaluated candidate entry geometry bounds and native world vertices or equivalent reproducible audit prove all solids exterior y[-.5,0], capmax .49, ground contact and central clearance. Cross-sections sample risers, side structure, terminal plane and actual W; supporting deck strip matches exact coupled floor candidate hash.','Candidate pair has exact semantic markers,1cell occupied/support cells, one shared registered rig and correct4 facing rotations. Report old neighbor support gaps as later scoped work.']},{'group':'exactStandaloneEntryAtlases','required':['Four actual native N/E/S/W static captures at384x704 published2x (or actual bound historical4x raw captures plus uniform whole-frame downsample recipe), transparentRGBA. Each is1frame,12fps,loopfalse,logical192x352/root96,248/sourceScale2, no fitting/cropping/per-view recolor.','Four-view registered contact sheet at native/enlarged and logical sizes; each standalone inspected on light/gray/dark. All exact atlas bytes and optional packed output hash-bound. A repeated study is a readability study only, not an invented self-tiling requirement.']},{'group':'coupledNativeAndIndependentJoin','required':['All4facings shared-scene native floor+entry depth-tested captures using actual accepted paired geometry, original floor root and rotated relative entryroot(0,-1.5,0); fixed uncropped context canvas/basis acrossfacings. Include shared plane/height cross-sections and full source-to-candidate context.','Separately export actual entry/floor sprites and independently assemble using actual consumer root/placement/draw-order utilities and original registration, without scene screenshot substitution, per-facing offsets, fitted scaling or hand mask. Show all4facings and quantify local RGB/alpha/visibility boundaries.','Current orderPlacements is expected sufficient only after proof. Include N floor-last, S/E/W entry-last output and native comparison; inspect caps/posts/undersides/terminal surface and contact with actual filtering at logical scale.','RGB+alpha detail crops through the contact on light/gray/dark, native and independent joins, ordinary viewer filtering plus x/y phases0,.25,.5,.75logicalpx. No physical run gap, no sustained visible crack/halo/ghost or wrong depth.']},{'group':'registeredRoleContext','required':['All4facings native and independently composed registered dock context with unchanged workshop/submarine placements and source/frozen reference neighbors, plus appropriate humanoid scale/clearance reference and ground-to-stair-to-deck path markers. No fitting or moving a human to conceal poor support.','Demonstrate centered width>=.76 and contact/no snag/obstacle throughout flight; native local/world ground support and terminal sections. Human/path evidence is visual/geometry review, not new gameplay implementation.','Actual catalog browser portrait390x844 and landscape844x390 screenshots with real candidate assets at consumer size/filtering, on light/gray/dark, including a full context and zoomed detail. Synthetic phone thumbnails may supplement but do not replace browser consumer evidence.']}], 'reviewPolicy':{'scores':'Comparative shapeVolume,color,lightingHighlights,materialDetail,artifactFreeReadability; observations support score, no arbitrary numeric pass threshold.','missingEvidence':'needs_evidence rather than approval','blockers':'At most three ranked observable blockers per later candidate','noApprovalNow':True,'scope':'Prep only: no source/production changes, no Git, no live Blender, no editor/adapter implementation or new agents.'}}
write('proposedcriteria.json',criteria);write('criteria.json',criteria)
